/**
 *圆锥载荷Primitive
 *
 * @export
 * @class SensorTaperedPrimitive
 */
const defaultValue = (value, fallback) =>
  value === undefined || value === null ? fallback : value;

export default class SensorTaperedPrimitive {
  constructor(options) {
    this._context = null;

    this._drawCommand1 = null;
    this._drawCommand2 = null;

    this._destroyed = false;
    this._offset = 0.0;

    this._onCreateDrawCommand = () => {};

    this.id = defaultValue(options.id, Cesium.createGuid());

    this.name = defaultValue(options.name, "圆锥载荷");

    this._show = defaultValue(options.show, true);

    this._outline = defaultValue(options.outline, true);

    this._outlineColor = defaultValue(
      options.outlineColor,
      new Cesium.Color(1.0, 1.0, 1.0, 1.0)
    );

    this._animation = defaultValue(options.animation, false);

    this._animationSpeed = defaultValue(options.animationSpeed, 10.0);

    this._position = defaultValue(
      options.position,
      Cesium.Cartesian3.ZERO
    );

    this._orientation = defaultValue(
      options.orientation,
      Cesium.Quaternion.IDENTITY
    );

    this._scale = defaultValue(options.scale, 1.0);

    this._modelMatrix = defaultValue(
      options.modelMatrix,
      Cesium.Matrix4.ZERO
    );

    this._color = defaultValue(
      options.color,
      new Cesium.Color(1.0, 0.0, 0.0, 1.0)
    );

    this._length = Math.abs(defaultValue(options.length, 1000.0));
    this._rHalfAngle = Math.abs(defaultValue(options.rHalfAngle, 15.0));

    if (this._modelMatrix === Cesium.Matrix4.ZERO) {
      this._computeModelMatrix();
    }
  }

  _computeModelMatrix() {
    if (this._orientation === Cesium.Quaternion.IDENTITY) {
      // 未设置姿态
      this._modelMatrix = Cesium.Transforms.eastNorthUpToFixedFrame(
        this._position
      );
    } else {
      // 已设置姿态
      // this._modelMatrix = Cesium.Matrix4.multiply(
      //   Cesium.Transforms.eastNorthUpToFixedFrame(this._position),
      //   Cesium.Matrix4.fromTranslationQuaternionRotationScale(
      //     new Cesium.Cartesian3(0, 0, 0),
      //     this._orientation,
      //     new Cesium.Cartesian3(this._scale, this._scale, this._scale),
      //     new Cesium.Matrix4()
      //   ),
      //   new Cesium.Matrix4()
      // );
      this._modelMatrix = Cesium.Matrix4.fromTranslationQuaternionRotationScale(
        this._position,
        this._orientation,
        new Cesium.Cartesian3(this._scale, this._scale, this._scale),
        new Cesium.Matrix4()
      );
    }
  }

  _generateGeometry() {
    const num = 36;
    //  定义顶点坐标数组
    const positions = new Float64Array((num + 1) * 3);
    const r = this._length * Math.tan(Cesium.Math.toRadians(this._rHalfAngle));
    // position ...
    for (let i = 0; i < num; i++) {
      positions[0 + i * 3] =
        r * Math.cos(Cesium.Math.toRadians((360 / num) * (i + 1)));
      positions[1 + i * 3] =
        r * Math.sin(Cesium.Math.toRadians((360 / num) * (i + 1)));
      positions[2 + i * 3] = -this._length;
    }
    // position（顶部）
    positions[(num + 1) * 3 - 3] = 0.0;
    positions[(num + 1) * 3 - 2] = 0.0;
    positions[(num + 1) * 3 - 1] = 0.0;
    // 定义纹理坐标数组
    const sts = new Float32Array((num + 1) * 2);
    // position ...
    for (let i = 0; i < num; i++) {
      sts[0 + i * 2] = 1.0;
      // 0.0 + 0.5 * Math.cos(Cesium.Math.toRadians(360 / num) * (i + 1));
      sts[1 + i * 2] = 1.0;
      // 0.0 + 0.5 * Math.sin(Cesium.Math.toRadians(360 / num) * (i + 1));
    }
    // position （顶部）
    sts[(num + 1) * 2 - 2] = 0.5;
    sts[(num + 1) * 2 - 1] = 0.5;
    //  定义索引数组
    const indices = new Uint16Array(num * 3);
    // triangle ...
    for (let i = 0; i < num; i++) {
      indices[0 + i * 3] = num;
      indices[1 + i * 3] = i;
      indices[2 + i * 3] = i == num - 1 ? 0 : i + 1;
    }
    const geometry = new Cesium.Geometry({
      attributes: {
        position: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.DOUBLE,
          componentsPerAttribute: 3,
          values: positions,
        }),
        // 设置纹理的时候需要配置
        st: new Cesium.GeometryAttribute({
          componentDatatype: Cesium.ComponentDatatype.FLOAT,
          componentsPerAttribute: 2,
          values: sts,
        }),
      },
      indices: indices,
      boundingSphere: Cesium.BoundingSphere.fromVertices(positions),
    });
    return geometry;
  }

  _generateBoundingVolume() {
    const center = this._position;
    const radius = this._length;
    const boundingVolume = new Cesium.BoundingSphere(center, radius * radius);
    return boundingVolume;
  }

  _generateGeometryPositions() {
    const num = 36;
    const r = this._length * Math.tan(Cesium.Math.toRadians(this._rHalfAngle));
    const positions = [];
    for (let i = 0; i <= num; i++) {
      const position = new Cesium.Cartesian3(
        r * Math.cos(Cesium.Math.toRadians((360 / num) * (i + 1))),
        r * Math.sin(Cesium.Math.toRadians((360 / num) * (i + 1))),
        -this._length
      );
      positions.push(position);
    }
    // 底部边坐标
    const borderPositions = positions.map((position) =>
      Cesium.Matrix4.multiplyByPoint(
        this._modelMatrix,
        position,
        new Cesium.Cartesian3()
      )
    );
    // 顶部点坐标
    const topPosition = Cesium.Matrix4.multiplyByPoint(
      this._modelMatrix,
      new Cesium.Cartesian3(0, 0, 0),
      new Cesium.Cartesian3()
    );
    // 底部点坐标
    const bottomPosition = Cesium.Matrix4.multiplyByPoint(
      this._modelMatrix,
      new Cesium.Cartesian3(0, 0, -this._length),
      new Cesium.Cartesian3()
    );
    // 方向向量
    const direction = Cesium.Cartesian3.normalize(
      Cesium.Cartesian3.subtract(
        topPosition,
        bottomPosition,
        new Cesium.Cartesian3()
      ),
      new Cesium.Cartesian3()
    );
    return { borderPositions, topPosition, bottomPosition, direction };
  }

  _createCommand(context) {
    if (!context) return;
    const geometry = this._generateGeometry();
    const boundingVolume = this._generateBoundingVolume();
    const vertexArray = Cesium.VertexArray.fromGeometry({
      geometry: geometry,
      context: context,
      attributeLocation:
        Cesium.GeometryPipeline.createAttributeLocations(geometry),
    });

    const shaderProgram = Cesium.ShaderProgram.fromCache({
      context: context,
      vertexShaderSource: `
            precision highp float;
            in vec3 position;
            in vec2 st;
            out vec3 v_position;
            out vec2 v_st;
            void main() {
                v_position = position;
                v_st = st;
                gl_Position = czm_projection * czm_modelView * vec4(position, 1.0);
            }
        `,
      fragmentShaderSource: `
        in vec2 v_st;
        uniform bool animation;
        uniform float animationSpeed;
        uniform vec4 color;
        uniform float count;
        void main() {
          vec2 st = v_st;
          vec4 fragColor = color;
          if(!animation){
            out_FragColor=fragColor;
            return;
          };
          float dis = distance(st, vec2(0.5, 0.5));
          float per = fract(czm_frameNumber * animationSpeed / 1000.0);
          if(count == 1.0){
            fragColor.a = color.a  * dis * (1.0 +  10.0 * (1.0 - 0.8));
            out_FragColor=fragColor;
          } else {
            float perDis = 1.0 / count;
            float disNum;
            float bl = 0.0;
            for(int i = 0; i <= 10; i++){
                if(float(i) <= count){
                disNum = perDis * float(i) - dis + per / count;
                if(disNum > 0.0){
                  if(disNum < perDis){
                  bl = 1.0 - disNum / perDis;
                  }
                  else if(disNum - perDis < perDis){
                    bl = 1.0 - abs(1.0 - disNum / perDis);
                  }
                  fragColor.a = pow(bl,(1.0 +  10.0 * (1.0 - 0.8)));
                  out_FragColor=fragColor;
                }
              }
            }
          }
        }
        `,
      attributeLocation:
        Cesium.GeometryPipeline.createAttributeLocations(geometry),
    });

    const uniformMap = {
      // color: () => {
      //   return this._color;
      // },
      animation: () => {
        return this._animation;
      },
      animationSpeed: () => {
        return this._animationSpeed;
      },
      count: () => {
        return 10.0;
      },
    };

    const renderState = Cesium.RenderState.fromCache({
      depthTest: {
        enabled: true, // 开启深度检测
      },
      cull: {
        enabled: false,
      },
    });

    // DrawCommand详情：  https://blog.csdn.net/esoft_weixiuyong/article/details/122338351
    this._drawCommand1 = new Cesium.DrawCommand({
      vertexArray: vertexArray,
      shaderProgram: shaderProgram,
      uniformMap: {
        ...uniformMap,
        color: () => {
          return this._color;
        },
      },
      renderState: renderState,
      boundingVolume: boundingVolume,
      pass: Cesium.Pass.TRANSLUCENT,
      receiveShadows: true,
      castShadows: true,
      primitiveType: Cesium.PrimitiveType.TRIANGLES,
      modelMatrix: this._modelMatrix,
    });
    this._drawCommand2 = new Cesium.DrawCommand({
      vertexArray: vertexArray,
      shaderProgram: shaderProgram,
      uniformMap: {
        ...uniformMap,
        color: () => {
          return this._outlineColor;
        },
      },
      renderState: renderState,
      boundingVolume: boundingVolume,
      pass: Cesium.Pass.TRANSLUCENT,
      receiveShadows: true,
      castShadows: true,
      primitiveType: Cesium.PrimitiveType.LINES,
      modelMatrix: this._modelMatrix,
    });

    const geometryPositions = this._generateGeometryPositions();
    this._onCreateDrawCommand({ geometryPositions });
  }

  destroy() {
    this._destroyed = true;
    return Cesium.destroyObject(this);
  }

  isDestroyed() {
    return this._destroyed;
  }

  // 显隐
  set show(show) {
    this._show = show;
  }
  get show() {
    return this._show;
  }

  // 边框
  set outline(outline) {
    this._outline = outline;
  }
  get outline() {
    return this._outline;
  }

  // 边框颜色
  set outlineColor(outlineColor) {
    this._outlineColor = outlineColor;
  }
  get outlineColor() {
    return this._outlineColor;
  }

  // 动画
  set animation(animation) {
    this._animation = animation;
    this._createCommand(this._context);
  }
  get animation() {
    return this._animation;
  }

  // 动画速度
  set animationSpeed(animationSpeed) {
    this._animationSpeed = animationSpeed;
    this._createCommand(this._context);
  }
  get animationSpeed() {
    return this._animationSpeed;
  }

  // 位置
  set position(position) {
    this._position = position;
    this._computeModelMatrix();
    this._createCommand(this._context);
  }
  get position() {
    return this._position;
  }

  // 姿态
  set orientation(orientation) {
    this._orientation = orientation;
    this._computeModelMatrix();
    this._createCommand(this._context);
  }
  get orientation() {
    return this._orientation;
  }

  // 缩放
  set scale(scale) {
    this._scale = scale;
    this._computeModelMatrix();
    this._createCommand(this._context);
  }
  get scale() {
    return this._scale;
  }

  // 模型矩阵
  set modelMatrix(modelMatrix) {
    this._modelMatrix = modelMatrix;
    this._createCommand(this._context);
  }
  get modelMatrix() {
    return this._modelMatrix;
  }

  // color
  set color(color) {
    this._color = color;
    this._createCommand(this._context);
  }
  get color() {
    return this._color;
  }

  // length
  set length(length) {
    this._length = Math.abs(length);
    this._createCommand(this._context);
  }
  get length() {
    return this._length;
  }

  // rHalfAngle
  set rHalfAngle(rHalfAngle) {
    this._rHalfAngle = Math.abs(rHalfAngle);
    this._createCommand(this._context);
  }
  get rHalfAngle() {
    return this._rHalfAngle;
  }

  update(frameState) {
    this._context = frameState.context;
    if (!this._show) return;
    if (!this._drawCommand1 && !this._drawCommand2) {
      this._createCommand(this._context);
    }
    frameState.commandList.push(this._drawCommand1);
    if (!this._outline) return;
    frameState.commandList.push(this._drawCommand2);
  }
}

/**
 * 航天任务模拟器 - 轨迹计算模块
 * 基于简化物理模型生成发射轨迹
 */

// 物理常量
export const EARTH_RADIUS = 6378137; // WGS84 赤道半径 (m)
export const GM = 3.986004418e14; // 地球引力常数 (m³/s²)
export const TARGET_ORBIT_ALT = 400000; // 目标轨道高度 400km
export const ORBITAL_VELOCITY = Math.sqrt(
  GM / (EARTH_RADIUS + TARGET_ORBIT_ALT),
); // ≈7672 m/s

// 酒泉卫星发射中心
export const LAUNCH_LON = 100.2917;
export const LAUNCH_LAT = 40.9583;

// 飞行阶段定义
export const FLIGHT_PHASES = [
  {
    name: "点火起飞",
    t0: 0,
    t1: 10,
    alt0: 3,
    alt1: 600,
    vel0: 0,
    vel1: 150,
    pitch0: 90,
    pitch1: 90,
  },
  {
    name: "垂直爬升",
    t0: 10,
    t1: 60,
    alt0: 600,
    alt1: 25000,
    vel0: 150,
    vel1: 2500,
    pitch0: 90,
    pitch1: 78,
  },
  {
    name: "重力转弯",
    t0: 60,
    t1: 140,
    alt0: 25000,
    alt1: 100000,
    vel0: 2500,
    vel1: 5500,
    pitch0: 78,
    pitch1: 30,
  },
  {
    name: "二级推进",
    t0: 140,
    t1: 240,
    alt0: 100000,
    alt1: 250000,
    vel0: 5500,
    vel1: 6800,
    pitch0: 30,
    pitch1: 10,
  },
  {
    name: "三级推进",
    t0: 240,
    t1: 280,
    alt0: 250000,
    alt1: 400000,
    vel0: 6800,
    vel1: ORBITAL_VELOCITY,
    pitch0: 10,
    pitch1: 0,
  },
  {
    name: "轨道运行",
    t0: 280,
    t1: 560,
    alt0: 400000,
    alt1: 400000,
    vel0: ORBITAL_VELOCITY,
    vel1: ORBITAL_VELOCITY,
    pitch0: 0,
    pitch1: 0,
  },
];

// 级间分离时间点（秒）
export const BOOSTER_SEP_TIME = 100; // 助推器分离
export const STAGE1_SEP_TIME = 140; // 一级分离
export const FAIRING_JETTISON_TIME = 200; // 整流罩抛离
export const STAGE2_SEP_TIME = 240; // 二级分离
export const STAGE3_SEP_TIME = 280; // 三级分离 / 卫星部署
export const TOTAL_FLIGHT_TIME = 560; // 总飞行时间

// --- 辅助函数 ---
function lerp(a, b, t) {
  return a + (b - a) * t;
}
function easeInOut(t) {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}
function toRad(deg) {
  return (deg * Math.PI) / 180;
}
function toDeg(rad) {
  return (rad * 180) / Math.PI;
}

function findPhase(t) {
  for (const p of FLIGHT_PHASES) {
    if (t >= p.t0 && t <= p.t1) return p;
  }
  return FLIGHT_PHASES[FLIGHT_PHASES.length - 1];
}

function computeFlightParams(t) {
  const phase = findPhase(t);
  const frac = (t - phase.t0) / (phase.t1 - phase.t0);
  return {
    alt: lerp(phase.alt0, phase.alt1, easeInOut(frac)),
    vel: lerp(phase.vel0, phase.vel1, frac),
    pitch: lerp(phase.pitch0, phase.pitch1, frac),
    phaseName: phase.name,
  };
}

/**
 * 生成主轨迹（火箭飞行 + 卫星入轨）
 * @param {number} dt 时间步长（秒），默认1秒
 * @returns {Array<{time, lon, lat, alt, vel, pitch, phaseName}>}
 */
export function generateTrajectory(dt = 1) {
  const points = [];
  const orbitOmega = ORBITAL_VELOCITY / (EARTH_RADIUS + TARGET_ORBIT_ALT);

  let cumLon = LAUNCH_LON;
  let cumLat = LAUNCH_LAT;

  for (let t = 0; t <= TOTAL_FLIGHT_TIME; t += dt) {
    const p = computeFlightParams(t);

    // 累计经度变化（基于水平速度分量）
    const vH = p.vel * Math.cos(toRad(p.pitch));
    const dLon =
      ((vH * dt) / (EARTH_RADIUS * Math.cos(toRad(cumLat)))) * toDeg(1);
    cumLon += dLon;

    // 轨道阶段纬度振荡（轨道倾角效应）
    if (t > STAGE3_SEP_TIME) {
      const orbitT = t - STAGE3_SEP_TIME;
      cumLat = LAUNCH_LAT * Math.cos(orbitOmega * orbitT);
    }

    points.push({
      time: t,
      lon: cumLon,
      lat: cumLat,
      alt: p.alt,
      vel: p.vel,
      pitch: p.pitch,
      phaseName: p.phaseName,
    });
  }
  return points;
}

/**
 * 生成分离后的火箭坠落轨迹
 * @param {number} sepTime  分离时刻
 * @param {number} sepLon   分离经度
 * @param {number} sepLat   分离纬度
 * @param {number} sepAlt   分离高度
 * @param {number} sepVel   分离时速度
 * @param {number} sepPitch 分离时俯仰角
 * @param {number} duration 坠落持续时间（秒）
 * @returns {Array<{time, lon, lat, alt}>}
 */
export function generateFallingTrajectory(
  sepTime,
  sepLon,
  sepLat,
  sepAlt,
  sepVel,
  sepPitch,
  duration = 120,
) {
  const points = [];
  const dt = 1;
  const vH0 = sepVel * Math.cos(toRad(sepPitch));
  const vV0 = sepVel * Math.sin(toRad(sepPitch));

  let lon = sepLon;
  let lat = sepLat;
  let alt = sepAlt;
  let vH = vH0;
  let vV = vV0;

  for (let i = 0; i <= duration; i += dt) {
    points.push({ time: sepTime + i, lon, lat, alt: Math.max(0, alt) });

    vV -= 9.8 * dt; // 重力减速
    vH *= 0.99; // 大气阻力
    alt += vV * dt;
    const dLon = ((vH * dt) / (EARTH_RADIUS * Math.cos(toRad(lat)))) * toDeg(1);
    lon += dLon;

    if (alt <= 0) break;
  }
  return points;
}

/**
 * 轨道计算模块 — satellite.js + 六根数
 */
import { satellite } from "satellite.js";

const EARTH_RADIUS = 6378.137; // km
const GM = 398600.4418; // km³/s²

// ─── 度/弧度转换 ───
function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }

// ─── 经纬高 → ECEF (km) ───
function llaToEcef(lon, lat, altKm) {
  const r = EARTH_RADIUS + altKm;
  const clat = Math.cos(rad(lat)), slat = Math.sin(rad(lat));
  const clon = Math.cos(rad(lon)), slon = Math.sin(rad(lon));
  return [r * clat * clon, r * clat * slon, r * slat];
}

// ─── 根据六根数或 TLE 生成完整轨道（ECEF 坐标数组, 米单位） ───
export function generateOrbitPath(config) {
  let satrec;
  const { tleLine1, tleLine2 } = config;

  if (tleLine1 && tleLine2) {
    // 使用 TLE
    satrec = satellite.twoline2satrec(tleLine1, tleLine2);
  } else {
    // 使用六根数
    const {
      altitude = 400,
      eccentricity = 0,
      inclination = 43,
      raan = 0,
      argPerigee = 0,
      trueAnomaly = 0,
    } = config;
    const semiMajor = EARTH_RADIUS + altitude;
    const period = 2 * Math.PI * Math.sqrt(Math.pow(semiMajor, 3) / GM);
    const mm = (86400 / period).toFixed(8);
    const eccStr = String(Math.round(eccentricity * 1e7)).padStart(7, '0');
    const meanAnomaly = trueAnomaly; // 圆轨道时真近点角≈平近点角
    satrec = satellite.twoline2satrec(
      "1 99999U 00000A   24001.00000000  .00000000  00000-0  00000-0 0  0001",
      `2 99999 ${inclination.toFixed(4)} ${raan.toFixed(4)} ${eccStr} ${argPerigee.toFixed(4)} ${meanAnomaly.toFixed(4)} ${mm} 00001`
    );
  }

  const semiMajor = EARTH_RADIUS + (config.altitude || 400);
  const period = 2 * Math.PI * Math.sqrt(Math.pow(semiMajor, 3) / GM);

  const points = [];
  const dt = 0.5;
  for (let t = 0; t <= period; t += dt) {
    try {
      const date = new Date(Date.now() + t * 1000);
      const posVel = satellite.propagate(satrec, date);
      if (!posVel) continue;
      const posEci = posVel.position;
      // 参考 test.html：用 gstime + eciToEcf 转换为地固系
      const gmst = satellite.gstimeFromDate(date);
      const posEcf = satellite.eciToEcf(posEci, gmst);
      const x = posEcf.x * 1000, y = posEcf.y * 1000, z = posEcf.z * 1000;
      if (isNaN(x) || isNaN(y) || isNaN(z)) continue;
      points.push([x, y, z]);
    } catch (e) { continue; }
  }
  return points.filter(p => p.every(v => isFinite(v)));
}

// ─── 计算卫星轨道周期 ───
export function getOrbitPeriod(config) {
  const semiMajor = EARTH_RADIUS + (config.altitude || 400);
  return 2 * Math.PI * Math.sqrt(Math.pow(semiMajor, 3) / GM);
}

// ─── 计算入轨速度 ───
export function getOrbitalVelocity(config) {
  const r = (EARTH_RADIUS + (config.altitude || 400)) * 1000; // m
  return Math.sqrt(3.986004418e14 / r); // m/s
}

// ─── 计算发射方位角（基于轨道倾角和发射场纬度）───
function calculateLaunchAzimuth(inclinationDeg, latDeg) {
  const latRad = rad(latDeg);
  const incRad = rad(inclinationDeg);
  const sinAz = Math.cos(incRad) / Math.cos(latRad);
  if (Math.abs(sinAz) > 1) {
    // 无法从该纬度直接发射到此倾角，使用最佳逼近方位角
    return inclinationDeg > 90 ? 135 : 45;
  }
  let az = Math.asin(sinAz) * 180 / Math.PI;
  // 顺行轨道(i<90°)向东北方向发射，逆行轨道(i>90°)向东南方向发射
  if (inclinationDeg > 90) az = 180 - az;
  return az; // 从正北顺时针的度数
}

// ─── 计算入轨点：SGP4 在上升段结束时刻(t=ascentTime)的位置 ───
function findInsertionPoint(satrec, site, timeRef, ascentTime) {
  if (!satrec || satrec.error) {
    return { lon: site.lon + 15, lat: site.lat * 0.3, alt: 400000, t: ascentTime };
  }
  const baseTime = timeRef || Date.now();
  try {
    const date = new Date(baseTime + ascentTime * 1000);
    const pv = satellite.propagate(satrec, date);
    if (!pv) throw new Error('no pv');
    const gmst = satellite.gstimeFromDate(date);
    const ecf = satellite.eciToEcf(pv.position, gmst);
    const r = Math.sqrt(ecf.x * ecf.x + ecf.y * ecf.y + ecf.z * ecf.z);
    const lat = Math.asin(ecf.z / r) * 180 / Math.PI;
    const lon = Math.atan2(ecf.y, ecf.x) * 180 / Math.PI;
    const altKm = r - EARTH_RADIUS;
    return { lon, lat, alt: altKm * 1000, t: ascentTime };
  } catch (e) {
    return { lon: site.lon + 15, lat: site.lat * 0.3, alt: 400000, t: ascentTime };
  }
}

// ─── 生成从发射场到入轨的飞行轨迹 ───
// 流程：TLE/六根数 → 入轨点(终点) + 发射场(起点) → 速度积分地面轨迹 + 合理级间分离时间
export function generateLaunchTrajectory(config) {
  const site = config.launchSite || { lon: 110.95, lat: 19.61 };
  const targetAlt = (config.altitude || 400) * 1000; // m
  const orbVel = getOrbitalVelocity(config); // m/s

  // 从 TLE 或六根数提取轨道倾角，计算发射方位角
  const satrec = buildSatrec(config);
  let inclination = 43;
  if (satrec && !satrec.error) {
    inclination = satrec.inc * 180 / Math.PI;
  }
  const launchAz = calculateLaunchAzimuth(inclination, site.lat);

  // 时间缩放（基于目标轨道高度）
  const timeScale = Math.sqrt(targetAlt / 400000);

  // 高度/速度缩放因子
  const sAlt = targetAlt / 400000;
  const sVel = orbVel / 7672;

  // ── 飞行阶段时间节点 ──
  const tIgnition     = 10;
  const tVertEnd      = Math.round(60 * timeScale);
  const tBoosterSep   = Math.round(120 * timeScale);  // 助推器分离 = 重力转弯结束
  const tStage1Sep    = Math.round(160 * timeScale);   // 一级分离 = 一级推进结束（在二级点火前）
  const tFairingSep   = Math.round(190 * timeScale);   // 整流罩抛离 = 二级推进中期
  const tStage2Sep    = Math.round(220 * timeScale);   // 二级分离 = 二级推进结束（在三级点火前）
  const tOrbitInsert  = Math.round(280 * timeScale);   // 星箭分离/入轨 = 三级推进结束
  // 入轨后展示半个轨道周期，让用户能明显看到卫星在轨运动
  const orbitPeriod = (satrec && !satrec.error)
    ? Math.round(2 * Math.PI / satrec.no * 60)
    : Math.round(2 * Math.PI * Math.sqrt(Math.pow(EARTH_RADIUS + (config.altitude || 400), 3) / GM));
  const totalTime     = tOrbitInsert + Math.max(600, Math.round(orbitPeriod / 2));

  // ── 7阶段飞行剖面 ──
  // 助推器+一级: 阶段0~2 → 一级单独: 阶段3 → 二级: 阶段4 → 三级: 阶段5 → 轨道: 阶段6
  const phases = [
    { name: "点火起飞", t0: 0,            t1: tIgnition,
      alt0: 40,              alt1: 600,
      vel0: 0,               vel1: 150 * sVel,
      pitch0: 90,            pitch1: 90 },
    { name: "垂直爬升", t0: tIgnition,   t1: tVertEnd,
      alt0: 600,             alt1: 25000 * sAlt,
      vel0: 150 * sVel,      vel1: 2500 * sVel,
      pitch0: 90,            pitch1: 78 },
    { name: "重力转弯", t0: tVertEnd,    t1: tBoosterSep,
      alt0: 25000 * sAlt,    alt1: 70000 * sAlt,
      vel0: 2500 * sVel,     vel1: 4000 * sVel,
      pitch0: 78,             pitch1: 45 },
    { name: "一级推进", t0: tBoosterSep, t1: tStage1Sep,
      alt0: 70000 * sAlt,    alt1: 120000 * sAlt,
      vel0: 4000 * sVel,     vel1: 5500 * sVel,
      pitch0: 45,             pitch1: 25 },
    { name: "二级推进", t0: tStage1Sep,  t1: tStage2Sep,
      alt0: 120000 * sAlt,   alt1: 250000 * sAlt,
      vel0: 5500 * sVel,     vel1: 6800 * sVel,
      pitch0: 25,             pitch1: 10 },
    { name: "三级推进", t0: tStage2Sep,   t1: tOrbitInsert,
      alt0: 250000 * sAlt,   alt1: targetAlt,
      vel0: 6800 * sVel,     vel1: orbVel,
      pitch0: 10,             pitch1: 0 },
    { name: "轨道运行", t0: tOrbitInsert, t1: totalTime,
      alt0: targetAlt,       alt1: targetAlt,
      vel0: orbVel,          vel1: orbVel,
      pitch0: 0,              pitch1: 0 },
  ];

  // ── 计算入轨点 = SGP4 在上升段结束时刻(t=tOrbitInsert)的位置 ──
  const insertionPoint = findInsertionPoint(satrec, site, Date.now(), tOrbitInsert);
  const orbitT0 = insertionPoint.t; // = tOrbitInsert

  // ── 辅助函数 ──
  function lerp(a, b, t) { return a + (b - a) * t; }
  function easeInOut(t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; }
  function findPhase(t) {
    for (const p of phases) {
      if (t >= p.t0 && t <= p.t1) return p;
    }
    return phases[phases.length - 1];
  }

  // ── 预计算入轨后的 SGP4 轨迹点（经纬高），用于轨道运行段 ──
  // 关键：经度连续化，防止 ±180° 跳跃导致 Cartesian3.fromDegrees 闪动
  const orbitPoints = [];
  let prevLon = null;
  let lonOffset = 0;
  if (satrec && !satrec.error) {
    const now = Date.now();
    for (let t = orbitT0; t <= orbitT0 + (totalTime - tOrbitInsert) + 10; t += 1) {
      try {
        const date = new Date(now + t * 1000);
        const pv = satellite.propagate(satrec, date);
        if (!pv) continue;
        const gmst = satellite.gstimeFromDate(date);
        const ecf = satellite.eciToEcf(pv.position, gmst);
        const r = Math.sqrt(ecf.x * ecf.x + ecf.y * ecf.y + ecf.z * ecf.z);
        const lat = Math.asin(ecf.z / r) * 180 / Math.PI;
        let lon = Math.atan2(ecf.y, ecf.x) * 180 / Math.PI;
        // 经度连续化：检测 ±180° 跳变，累加偏移
        if (prevLon !== null) {
          if (lon - prevLon > 180) lonOffset -= 360;
          else if (lon - prevLon < -180) lonOffset += 360;
        }
        lon += lonOffset;
        prevLon = lon;
        const altKm = r - EARTH_RADIUS;
        orbitPoints.push({ t: t - orbitT0, lon, lat, alt: altKm * 1000 });
      } catch (e) { continue; }
    }
  }
  // 回退：如果 SGP4 失败，用静态入轨点
  if (orbitPoints.length === 0) {
    orbitPoints.push({ t: 0, lon: insertionPoint.lon, lat: insertionPoint.lat, alt: insertionPoint.alt });
  }

  // ── 计算每个时刻的飞行参数和累积水平速度 ──
  const dt = 1;
  const stepData = [];
  let cumHorizVel = 0;
  for (let t = 0; t <= totalTime; t += dt) {
    const phase = findPhase(t);
    const frac = (t - phase.t0) / Math.max(1, phase.t1 - phase.t0);
    const vel = lerp(phase.vel0, phase.vel1, frac);
    const pitch = lerp(phase.pitch0, phase.pitch1, frac);
    const vH = vel * Math.cos(rad(pitch));
    if (t <= tOrbitInsert) {
      cumHorizVel += vH * dt;
    }
    stepData.push({ t, phase, frac, vel, pitch, vH, cumHorizVel });
  }
  const totalHorizVel = cumHorizVel;

  // ── 入轨点 = orbitPoints[0]（SGP4 在 tOrbitInsert 时刻的位置）──
  const insLon = orbitPoints[0].lon;
  const insLat = orbitPoints[0].lat;
  const insAlt = orbitPoints[0].alt;

  // ── 发射场到入轨点的经纬度差 ──
  let dLonTotal = insLon - site.lon;
  while (dLonTotal > 180) dLonTotal -= 360;
  while (dLonTotal < -180) dLonTotal += 360;
  const dLatTotal = insLat - site.lat;

  // ── 生成轨迹点 ──
  // 上升段：从发射场按水平速度积分比例插值到入轨点
  // 入轨点处最后 3 秒平滑混合到 SGP4 位置，确保无缝衔接
  // 轨道段：直接使用 SGP4 预计算位置
  const blendDur = 3;
  const points = stepData.map(sd => {
    const alt = lerp(sd.phase.alt0, sd.phase.alt1, easeInOut(sd.frac));

    let lon, lat, finalAlt;
    if (sd.t <= tOrbitInsert) {
      // 上升段
      const distFrac = totalHorizVel > 0 ? sd.cumHorizVel / totalHorizVel : 0;
      lon = site.lon + dLonTotal * distFrac;
      lat = site.lat + dLatTotal * distFrac;
      finalAlt = alt;

      // 入轨前 blendDur 秒：平滑混合到 SGP4 入轨点位置
      if (sd.t >= tOrbitInsert - blendDur) {
        const blendT = (sd.t - (tOrbitInsert - blendDur)) / blendDur; // 0→1
        const easedT = blendT < 0.5 ? 2 * blendT * blendT : 1 - Math.pow(-2 * blendT + 2, 2) / 2;
        lon = lon * (1 - easedT) + insLon * easedT;
        lat = lat * (1 - easedT) + insLat * easedT;
        finalAlt = finalAlt * (1 - easedT) + insAlt * easedT;
      }
    } else {
      // 轨道运行段：使用 SGP4 预计算点（索引直接对应）
      const orbitT = Math.round(sd.t - tOrbitInsert);
      const idx = Math.max(0, Math.min(orbitPoints.length - 1, orbitT));
      lon = orbitPoints[idx].lon;
      lat = orbitPoints[idx].lat;
      finalAlt = orbitPoints[idx].alt;
    }

    return {
      time: sd.t,
      lon,
      lat,
      alt: finalAlt,
      vel: sd.vel,
      pitch: sd.pitch,
      phaseName: sd.phase.name,
    };
  });

  // ── 级间分离事件时间 ──
  // 分离事件在阶段交界处触发，确保分离后再点火下一级
  const eventTimes = {
    boosterSep: tBoosterSep,    // 重力转弯结束 → 助推器分离
    stage1Sep:  tStage1Sep,     // 一级推进结束 → 一级分离（二级点火前）
    fairingSep: tFairingSep,    // 二级推进中期 → 整流罩抛离
    stage2Sep:  tStage2Sep,     // 二级推进结束 → 二级分离（三级点火前）
    stage3Sep:  tOrbitInsert,   // 三级推进结束 → 星箭分离/入轨
  };

  return { points, totalTime, eventTimes };
}

// ─── 生成入轨后卫星位置（用于火箭模型在轨动画）───
export function generateSatelliteOrbit(config, startTime, duration) {
  const points = [];
  const satrec = buildSatrec(config);
  if (!satrec) return points;
  for (let t = 0; t <= duration; t += 0.5) {
    try {
      const date = new Date(2024, 0, 1, 0, 0, t);
      const posVel = satellite.propagate(satrec, date);
      if (!posVel) continue;
      const gmst = satellite.gstimeFromDate(date);
      const ecf = satellite.eciToEcf(posVel.position, gmst);
      // CallbackProperty 需要地固系(ECF)坐标
      const x = ecf.x * 1000, y = ecf.y * 1000, z = ecf.z * 1000;
      if (isNaN(x) || isNaN(y) || isNaN(z)) continue;
      points.push({ time: startTime + t, x, y, z });
    } catch (e) { continue; }
  }
  return points;
}

export function buildSatrec(config) {
  const { tleLine1, tleLine2 } = config;
  if (tleLine1 && tleLine2) {
    const sr = satellite.twoline2satrec(tleLine1, tleLine2);
    if (sr && !sr.error) return sr;
  }
  const {
    altitude = 400,
    eccentricity = 0,
    inclination = 43,
    raan = 0,
    argPerigee = 0,
    trueAnomaly = 0,
  } = config;
  const semiMajor = EARTH_RADIUS + altitude;
  const period = 2 * Math.PI * Math.sqrt(Math.pow(semiMajor, 3) / GM);
  const mm = (86400 / period).toFixed(8);
  const eccStr = String(Math.round(eccentricity * 1e7)).padStart(7, '0');
  const sr = satellite.twoline2satrec(
    "1 99999U 00000A   24001.00000000  .00000000  00000-0  00000-0 0  0001",
    `2 99999 ${inclination.toFixed(4)} ${raan.toFixed(4)} ${eccStr} ${argPerigee.toFixed(4)} ${trueAnomaly.toFixed(4)} ${mm} 00001`
  );
  return sr;
}

// ─── 生成轨道实体（参考 test.html：SampledPositionProperty + path + ECI 坐标）───
export function createOrbitEntity(config, CesiumRef) {
  const satrec = buildSatrec(config || { altitude: 400, eccentricity: 0, inclination: 43, raan: 0, argPerigee: 0, trueAnomaly: 0 });
  const semiMajor = EARTH_RADIUS + ((config && config.altitude) || 400);
  const periodSec = 2 * Math.PI * Math.sqrt(Math.pow(semiMajor, 3) / GM);
  const Cesium = CesiumRef || window.Cesium;

  const now = Date.now();
  const startTime = Cesium.JulianDate.fromDate(new Date(now));
  const endTime = Cesium.JulianDate.addSeconds(startTime, periodSec, new Cesium.JulianDate());

  const positionProperty = new Cesium.SampledPositionProperty();
  // 每1秒一个采样点（密集插值）
  const totalSteps = Math.ceil(periodSec / 0.5);
  for (let i = 0; i <= totalSteps; i++) {
    const date = new Date(now + i * 0.5 * 1000);
    const pv = satellite.propagate(satrec, date);
    if (!pv) continue;
    const pos = pv.position;
    const jd = Cesium.JulianDate.fromDate(date);
    // 使用惯性系(ECI)坐标（参考 test.html 注释）
    positionProperty.addSample(jd, new Cesium.Cartesian3(pos.x * 1000, pos.y * 1000, pos.z * 1000));
  }
  positionProperty.setInterpolationOptions({
    interpolationDegree: 5,
    interpolationAlgorithm: Cesium.LagrangePolynomialApproximation,
  });

  const entity = new Cesium.Entity({
    availability: new Cesium.TimeIntervalCollection([
      new Cesium.TimeInterval({ start: startTime, stop: endTime })
    ]),
    position: positionProperty,
    path: {
      resolution: 60,
      material: new Cesium.PolylineGlowMaterialProperty({
        glowPower: 0.3,
        color: Cesium.Color.fromCssColorString("#00ff88"),
      }),
      width: 3,
      leadTime: periodSec,
      trailTime: 0,
    },
  });
  return entity;
}

